/** @type {import('next').NextConfig} */
const conf = {
    output: 'export',
    distDir: 'build',
    assetPrefix: `${process.env.NEXT_PUBLIC_BASE_PATH ? process.env.NEXT_PUBLIC_BASE_PATH : '/'}`,
    basePath: `${process.env.NEXT_PUBLIC_BASE_PATH ? process.env.NEXT_PUBLIC_BASE_PATH : ''}`,
    trailingSlash: !process.env.TRAILING_SLASH || process.env.TRAILING_SLASH !== 'off',
    env: {
        CURRENT_BRANCH: process.env.CURRENT_BRANCH ?? '',
    },
    images: {
        unoptimized: true, // Disable image optimization for static export compatibility
    },
    webpack: /** @type {import('next').NextConfig['webpack']} */ ((config) => {
        // Ignore source map warnings for @tabler/icons-react
        config.ignoreWarnings = [
            ...(config.ignoreWarnings || []),
            /Could not read source map .* tabler-icons-react\.js\.map/,
        ];

        return config
    }),
}

export default conf
---
TRAILING_SLASH=off
# NEXT_PUBLIC_PLAUSIBLE_DOMAIN=your-domain.com
# NEXT_PUBLIC_PLAUSIBLE_ANALYTICS_URL=https://plausible.io/your-domain.com

command_executions.command:
cd /workspace && (npx --yes serve@latest build -l 3000 > /tmp/serve.log 2>&1 &) && sleep 12 && curl -s -o /dev/null -w "root: %{http_code}
" http://localhost:3000/ && curl -s -o /dev/null -w "de: %{http_code}
" http://localhost:3000/de/ && curl -s -o /dev/null -w "fit-standards: %{http_code}
" http://localhost:3000/fit-standards/ && curl -s http://localhost:3000/ | grep -o "<title[^>]*>[^<]*</title>" | head -1

curl -s -o /dev/null -w "root: %{http_code}
" http://localhost:3000/ && curl -s -o /dev/null -w "de: %{http_code}
" http://localhost:3000/de/ && curl -s -o /dev/null -w "fit-standards: %{http_code}
" http://localhost:3000/fit-standards/ && curl -s -o /dev/null -w "resources: %{http_code}
" http://localhost:3000/resources/meta/ && curl -s http://localhost:3000/ | grep -o "<title[^>]*>[^<]*</title>" | head -1

echo "=== / ===" && curl -s -o /dev/null -w "%{http_code}
" http://localhost:3000/ && curl -s http://localhost:3000/ | grep -o '<title data-next-head="">[^<]*</title>' | head -1
echo "=== /de/ ===" && curl -s -o /dev/null -w "%{http_code}
" http://localhost:3000/de/
echo "=== /en/ ===" && curl -s -o /dev/null -w "%{http_code}
" http://localhost:3000/en/
echo "=== /fit-standards/ ===" && curl -s -o /dev/null -w "%{http_code}
" http://localhost:3000/fit-standards/
echo "=== /resources/meta/ ===" && curl -s -o /dev/null -w "%{http_code}
" http://localhost:3000/resources/meta/
